      display: grid;
      gap: 20px;
    }

    .form-field {
      display: grid;
      gap: 10px;
    }

    .checkbox-row {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 14px 16px;
      border: 1px solid rgba(148, 163, 184, 0.16);
      border-radius: 14px;
      background: rgba(15, 23, 42, 0.76);
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
