        element.textContent = options.text;
      }

      if (options.attrs) {
        Object.entries(options.attrs).forEach(([key, value]) => {
          element.setAttribute(key, value);
        });
      }

      children.forEach((child) => {
        element.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
      });

      return element;
    }

    function ConsentField() {
      const checkbox = createElement("input", {
        attrs: {
          id: "terms",
          name: "terms",
          type: "checkbox",
          required: ""
        }
      });

      const label = createElement("label", {
        attrs: {
          for: "terms"
        },
        text: "I agree to the Terms of Use"
      });

      const helper = createElement("p", {
        className: "helper-text",
        attrs: {
          id: "terms-help"
        },
        text: "Required to continue."
      });

      checkbox.setAttribute("aria-describedby", "terms-help");

      const copy = createElement("div", { className: "checkbox-copy" }, [label, helper]);
      const row = createElement("div", { className: "checkbox-row" }, [checkbox, copy]);

      return createElement("div", { className: "form-field" }, [row]);
    }

    function SubmitButton() {
      return createElement("button", {
        attrs: {
          type: "submit"
        },
        text: "Submit"
      });
    }

    function App() {
      const card = createElement("main", { className: "card" });
      const eyebrow = createElement("p", { className: "eyebrow", text: "Quick confirmation" });
